// Monolith-like CLI tool reimplementation
// Parses HTML/files and emits a single-file output.

use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process;
use std::time::SystemTime;

mod html;
mod url;
mod cli;

fn main() {
    let args: Vec<String> = env::args().collect();
    match cli::parse(&args) {
        Err(cli::CliError::Help) => {
            cli::print_help();
            process::exit(0);
        }
        Err(cli::CliError::Version) => {
            println!("monolith {}", env!("CARGO_PKG_VERSION"));
            process::exit(0);
        }
        Err(cli::CliError::Usage(msg)) => {
            eprint!("{}", msg);
            process::exit(2);
        }
        Ok(opts) => {
            if let Err(e) = run(opts) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
    }
}

fn run(opts: cli::Options) -> Result<(), String> {
    // Determine target kind & fetch contents
    let (doc_bytes, doc_url, is_local) = load_target(&opts)?;

    if !opts.quiet {
        eprintln!("{}", doc_url);
    }

    // Convert to UTF-8 string (assume UTF-8 for now).
    let input = String::from_utf8_lossy(&doc_bytes).into_owned();

    // Apply transformations.
    let mut out = html::transform(&input, &opts, &doc_url, is_local);

    // Prepend metadata comment if applicable.
    if !opts.no_metadata && html::looks_like_html(&out) {
        let timestamp = current_timestamp_iso();
        let comment = if is_local {
            format!("<!-- Saved from local source at {} using monolith v{} -->\n",
                    timestamp, env!("CARGO_PKG_VERSION"))
        } else {
            format!("<!-- Saved from {} at {} using monolith v{} -->\n",
                    doc_url, timestamp, env!("CARGO_PKG_VERSION"))
        };
        // Insert after doctype if present
        out = prepend_metadata_comment(&out, &comment);
    }

    // MHTML wrapping
    if opts.mhtml {
        out = html::wrap_mhtml(&out, &doc_url);
    }

    // Determine output path
    let output_path = resolve_output_path(&opts, &out);

    match output_path.as_deref() {
        Some("-") | None => {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            handle.write_all(out.as_bytes()).map_err(|e| e.to_string())?;
        }
        Some(path) => {
            fs::write(path, out.as_bytes()).map_err(|e| e.to_string())?;
        }
    }

    Ok(())
}

fn load_target(opts: &cli::Options) -> Result<(Vec<u8>, String, bool), String> {
    let target = &opts.target;
    if target == "-" {
        let mut buf = Vec::new();
        io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
        let url = opts.base_url.clone().unwrap_or_else(|| "http://localhost/".to_string());
        return Ok((buf, url, false));
    }
    // file:// scheme
    if let Some(p) = target.strip_prefix("file://") {
        let p = PathBuf::from(p);
        let b = fs::read(&p).map_err(|_| format!("could not retrieve target document"))?;
        return Ok((b, format!("file://{}", absolute(&p)), true));
    }
    // http(s) scheme or not - check if local file exists
    let looks_like_url = target.starts_with("http://") || target.starts_with("https://");
    let as_path = Path::new(target);
    if !looks_like_url && as_path.exists() {
        let b = fs::read(as_path).map_err(|_| format!("could not retrieve target document"))?;
        return Ok((b, format!("file://{}", absolute(as_path)), true));
    }
    // Treat as URL - we can't fetch, so report error similar to monolith.
    let url = if looks_like_url {
        target.clone()
    } else {
        format!("http://{}/", target.trim_start_matches('/'))
    };
    // Normalize to have trailing slash if just domain
    let url = normalize_url(&url);
    eprintln!("{} (error sending request for url ({}))", url, url);
    Err("could not retrieve target document".to_string())
}

fn normalize_url(s: &str) -> String {
    // If there's no path part after scheme://host, add /.
    if let Some(rest) = s.strip_prefix("http://") {
        if !rest.contains('/') { return format!("http://{}/", rest); }
    } else if let Some(rest) = s.strip_prefix("https://") {
        if !rest.contains('/') { return format!("https://{}/", rest); }
    }
    s.to_string()
}

fn absolute(p: &Path) -> String {
    match fs::canonicalize(p) {
        Ok(cp) => cp.to_string_lossy().to_string(),
        Err(_) => p.to_string_lossy().to_string(),
    }
}

fn prepend_metadata_comment(html: &str, comment: &str) -> String {
    // Find end of doctype
    let lower = html.to_ascii_lowercase();
    if let Some(pos) = lower.find("<!doctype") {
        if let Some(end) = html[pos..].find('>') {
            let insert_at = pos + end + 1;
            let mut s = String::new();
            s.push_str(&html[..insert_at]);
            s.push('\n');
            s.push_str(comment.trim_end_matches('\n'));
            s.push_str(&html[insert_at..]);
            return s;
        }
    }
    // else prepend at start
    let mut s = String::new();
    s.push_str(comment);
    s.push_str(html);
    s
}

fn current_timestamp_iso() -> String {
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default();
    let secs = now.as_secs() as i64;
    let (y, mo, d, h, mi, s) = epoch_to_ymdhms(secs);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, mo, d, h, mi, s)
}

fn epoch_to_ymdhms(secs: i64) -> (i32, u32, u32, u32, u32, u32) {
    // Convert seconds since Unix epoch to UTC Y-M-D H:M:S.
    let days = secs.div_euclid(86400);
    let remaining = secs.rem_euclid(86400) as u32;
    let h = remaining / 3600;
    let mi = (remaining % 3600) / 60;
    let s = remaining % 60;
    // Algorithm for civil date from days since epoch (Howard Hinnant).
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100);
    let mp = (5*doy + 2)/153;
    let d = doy - (153*mp + 2)/5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = y + if m <= 2 { 1 } else { 0 };
    (y as i32, m as u32, d as u32, h, mi, s)
}

fn resolve_output_path(opts: &cli::Options, content: &str) -> Option<String> {
    opts.output.as_ref().map(|p| expand_placeholders(p, content))
}

fn expand_placeholders(path: &str, content: &str) -> String {
    let mut s = path.to_string();
    if s.contains("%title%") {
        let t = html::extract_title(content).unwrap_or_default();
        s = s.replace("%title%", &t);
    }
    if s.contains("%timestamp%") {
        let ts = current_timestamp_iso().replace(':', "_");
        s = s.replace("%timestamp%", &ts);
    }
    s
}
RUST_EOF
echo "main.rs written"

