struct OptSpec {
    short: char,
    long: &'static str,
    takes_value: bool,
    value_name: &'static str,
}

const OPTS: &[OptSpec] = &[
    OptSpec{short:'a', long:"no-audio", takes_value:false, value_name:""},
    OptSpec{short:'b', long:"base-url", takes_value:true, value_name:"<http://localhost/>"},
    OptSpec{short:'B', long:"blacklist-domains", takes_value:false, value_name:""},
    OptSpec{short:'c', long:"no-css", takes_value:false, value_name:""},
    OptSpec{short:'C', long:"cookie-file", takes_value:true, value_name:"<cookies.txt>"},
    OptSpec{short:'d', long:"domain", takes_value:true, value_name:"<example.com>"},
    OptSpec{short:'e', long:"ignore-errors", takes_value:false, value_name:""},
    OptSpec{short:'E', long:"encoding", takes_value:true, value_name:"<UTF-8>"},
    OptSpec{short:'f', long:"no-frames", takes_value:false, value_name:""},
    OptSpec{short:'F', long:"no-fonts", takes_value:false, value_name:""},
    OptSpec{short:'i', long:"no-images", takes_value:false, value_name:""},
    OptSpec{short:'I', long:"isolate", takes_value:false, value_name:""},
    OptSpec{short:'j', long:"no-js", takes_value:false, value_name:""},
    OptSpec{short:'k', long:"insecure", takes_value:false, value_name:""},
    OptSpec{short:'m', long:"mhtml", takes_value:false, value_name:""},
    OptSpec{short:'M', long:"no-metadata", takes_value:false, value_name:""},
    OptSpec{short:'n', long:"unwrap-noscript", takes_value:false, value_name:""},
    OptSpec{short:'o', long:"output", takes_value:true, value_name:"<result.html>"},
    OptSpec{short:'q', long:"quiet", takes_value:false, value_name:""},
    OptSpec{short:'t', long:"timeout", takes_value:true, value_name:"<60>"},
    OptSpec{short:'u', long:"user-agent", takes_value:true, value_name:"<Firefox>"},
    OptSpec{short:'v', long:"no-video", takes_value:false, value_name:""},
    OptSpec{short:'h', long:"help", takes_value:false, value_name:""},
    OptSpec{short:'V', long:"version", takes_value:false, value_name:""},
];

fn find_short(c: char) -> Option<&'static OptSpec> { OPTS.iter().find(|o| o.short == c) }
fn find_long(name: &str) -> Option<&'static OptSpec> { OPTS.iter().find(|o| o.long == name) }

fn usage_line_for(flags: &[&OptSpec]) -> String {
    let mut required = String::new();
    for f in flags {
        if f.takes_value {
            required.push_str(&format!(" --{} {}", f.long, f.value_name));
        } else {
            required.push_str(&format!(" --{}", f.long));
        }
    }
    format!("Usage: executable{} <TARGET>\n", required)
}

pub fn parse(args: &[String]) -> Result<Options, CliError> {
    let mut opts = Options {
        target: String::new(),
        no_audio: false,
        base_url: None,
        blacklist_domains: false,
        no_css: false,
        cookie_file: None,
        domains: Vec::new(),
        ignore_errors: false,
        encoding: None,
        no_frames: false,
        no_fonts: false,
        no_images: false,
        isolate: false,
        no_js: false,
        insecure: false,
        mhtml: false,
        no_metadata: false,
        unwrap_noscript: false,
        output: None,
        quiet: false,
        timeout: 60,
        user_agent: None,
        no_video: false,
    };

    let mut positional: Vec<String> = Vec::new();
    let mut i = 1;
    let mut used_value_flags: Vec<&OptSpec> = Vec::new();
    let mut end_of_opts = false;

    while i < args.len() {
        let a = &args[i];
        if end_of_opts {
            positional.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" {
            end_of_opts = true;
            i += 1;
            continue;
        }
        if a == "-" {
            positional.push(a.clone());
            i += 1;
            continue;
        }
        if let Some(rest) = a.strip_prefix("--") {
            // long option
            let (name, inline) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(&rest[p+1..])),
                None => (rest, None),
            };
            let spec = match find_long(name) {
                Some(s) => s,
                None => return Err(unexpected_arg(a, &used_value_flags)),
            };
            if spec.long == "help" { return Err(CliError::Help); }
            if spec.long == "version" { return Err(CliError::Version); }
            if spec.takes_value {
                let val = if let Some(v) = inline {
                    v.to_string()
                } else {
                    if i + 1 >= args.len() {
                        return Err(CliError::Usage(format!(
                            "error: a value is required for '--{} {}' but none was supplied\n\nFor more information, try '--help'.\n",
                            spec.long, spec.value_name)));
                    }
                    i += 1;
                    args[i].clone()
                };
                apply_value(&mut opts, spec, &val)?;
                used_value_flags.push(spec);
            } else {
                apply_flag(&mut opts, spec);
            }
            i += 1;
            continue;
        }
        if let Some(rest) = a.strip_prefix("-") {
            if rest.is_empty() {
                positional.push(a.clone());
                i += 1;
                continue;
            }
            // short option(s): could be combined like -Mj or -tN
            let chars: Vec<char> = rest.chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                let spec = match find_short(c) {
                    Some(s) => s,
                    None => {
                        let bad = format!("-{}", c);
                        return Err(unexpected_arg(&bad, &used_value_flags));
                    }
                };
                if spec.long == "help" { return Err(CliError::Help); }
                if spec.long == "version" { return Err(CliError::Version); }
                if spec.takes_value {
                    let val: String = if j + 1 < chars.len() {
                        chars[j+1..].iter().collect()
                    } else {
                        if i + 1 >= args.len() {
                            return Err(CliError::Usage(format!(
                                "error: a value is required for '--{} {}' but none was supplied\n\nFor more information, try '--help'.\n",
                                spec.long, spec.value_name)));
                        }
                        i += 1;
                        args[i].clone()
                    };
                    apply_value(&mut opts, spec, &val)?;
                    used_value_flags.push(spec);
                    break;
                } else {
                    apply_flag(&mut opts, spec);
                    j += 1;
                }
            }
            i += 1;
            continue;
        }
        positional.push(a.clone());
        i += 1;
    }

    if positional.is_empty() {
        return Err(CliError::Usage(format!(
            "error: the following required arguments were not provided:\n  <TARGET>\n\n{}\nFor more information, try '--help'.\n",
            usage_line_for(&used_value_flags))));
    }
    if positional.len() > 1 {
        // unexpected extra - clap would say this too
        let extra = &positional[1];
        return Err(unexpected_arg(extra, &used_value_flags));
    }
    opts.target = positional.into_iter().next().unwrap();
    Ok(opts)
}

fn apply_flag(opts: &mut Options, spec: &OptSpec) {
    match spec.long {
        "no-audio" => opts.no_audio = true,
        "blacklist-domains" => opts.blacklist_domains = true,
        "no-css" => opts.no_css = true,
        "ignore-errors" => opts.ignore_errors = true,
        "no-frames" => opts.no_frames = true,
        "no-fonts" => opts.no_fonts = true,
        "no-images" => opts.no_images = true,
        "isolate" => opts.isolate = true,
        "no-js" => opts.no_js = true,
        "insecure" => opts.insecure = true,
        "mhtml" => opts.mhtml = true,
        "no-metadata" => opts.no_metadata = true,
        "unwrap-noscript" => opts.unwrap_noscript = true,
        "quiet" => opts.quiet = true,
        "no-video" => opts.no_video = true,
        _ => {}
    }
}

fn apply_value(opts: &mut Options, spec: &OptSpec, val: &str) -> Result<(), CliError> {
    match spec.long {
        "base-url" => opts.base_url = Some(val.to_string()),
        "cookie-file" => opts.cookie_file = Some(val.to_string()),
        "domain" => opts.domains.push(val.to_string()),
        "encoding" => opts.encoding = Some(val.to_string()),
        "output" => opts.output = Some(val.to_string()),
        "timeout" => {
            match val.parse::<u64>() {
                Ok(v) => opts.timeout = v,
                Err(_) => return Err(CliError::Usage(format!(
                    "error: invalid value '{}' for '--{} {}': invalid digit found in string\n\nFor more information, try '--help'.\n",
                    val, spec.long, spec.value_name))),
            }
        }
        "user-agent" => opts.user_agent = Some(val.to_string()),
        _ => {}
    }
    Ok(())
}

fn unexpected_arg(arg: &str, used: &[&OptSpec]) -> CliError {
    let tip = if arg.starts_with('-') {
        format!("\n  tip: to pass '{}' as a value, use '-- {}'\n", arg, arg)
    } else {
        String::new()
    };
    let usage = usage_line_builder(used);
    CliError::Usage(format!(
        "error: unexpected argument '{}' found\n{}\n{}\nFor more information, try '--help'.\n",
        arg, tip, usage))
}

fn usage_line_builder(used: &[&OptSpec]) -> String {
    let mut required = String::new();
    for f in used {
        if f.takes_value {
            required.push_str(&format!(" --{} {}", f.long, f.value_name));
        } else {
            required.push_str(&format!(" --{}", f.long));
        }
    }
    format!("Usage: executable [OPTIONS] <TARGET>\n")
}
