// Minimal URL handling utilities.

pub fn join(base: &str, rel: &str) -> String {
    if rel.is_empty() { return base.to_string(); }
    // Absolute URL
    if rel.contains("://") { return rel.to_string(); }
    // Data/javascript
    if rel.starts_with("data:") || rel.starts_with("javascript:") || rel.starts_with("mailto:") {
        return rel.to_string();
    }
    // Fragment-only
    if rel.starts_with('#') {
        return format!("{}{}", strip_fragment(base), rel);
    }
    // Protocol-relative
    if let Some(r) = rel.strip_prefix("//") {
        if let Some(scheme_end) = base.find("://") {
            return format!("{}://{}", &base[..scheme_end], r);
        }
        return format!("http://{}", r);
    }
    // Absolute path
    if rel.starts_with('/') {
        // Combine with base scheme://host
        if let Some(scheme_end) = base.find("://") {
            let after = &base[scheme_end+3..];
            let host_end = after.find('/').unwrap_or(after.len());
            return format!("{}{}", &base[..scheme_end+3+host_end], rel);
        }
        return rel.to_string();
    }
    // Relative path
    let base_no_frag = strip_fragment(base);
    let base_no_q = match base_no_frag.find('?') { Some(p) => &base_no_frag[..p], None => base_no_frag.as_str() };
    // strip last path component
    if let Some(scheme_end) = base_no_q.find("://") {
        let rest = &base_no_q[scheme_end+3..];
        if let Some(first_slash) = rest.find('/') {
            let last_slash = rest.rfind('/').unwrap_or(first_slash);
            let dir = &base_no_q[..scheme_end+3+last_slash+1];
            return format!("{}{}", dir, rel);
        } else {
            return format!("{}/{}", base_no_q, rel);
        }
    }
    rel.to_string()
}

fn strip_fragment(s: &str) -> String {
    match s.find('#') { Some(p) => s[..p].to_string(), None => s.to_string() }
}
