// HTML transformations.

use crate::cli::Options;
use crate::url;

/// Whether the content looks like HTML (very rough heuristic).
pub fn looks_like_html(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    lower.contains("<html") || lower.contains("<!doctype") || lower.contains("<body") || lower.contains("<head")
        || lower.contains("<div") || lower.contains("<p") || lower.contains("<span") || lower.contains("<script")
        || lower.contains("<h1") || lower.contains("<style") || lower.contains("<a ") || lower.contains("<img")
        || lower.contains("<meta") || lower.contains("<!--")
}

pub fn extract_title(s: &str) -> Option<String> {
    let lower = s.to_ascii_lowercase();
    let start = lower.find("<title")?;
    let after = &s[start..];
    let gt = after.find('>')?;
    let after_tag = &after[gt+1..];
    let end_rel = after_tag.to_ascii_lowercase().find("</title>")?;
    Some(after_tag[..end_rel].trim().to_string())
}

fn ensure_html_wrapper(mut s: String) -> String {
    let lower = s.to_ascii_lowercase();
    if !lower.contains("<html") {
        let doctype_end = if let Some(p) = lower.find("<!doctype") {
            s[p..].find('>').map(|e| p + e + 1)
        } else { None };
        let (prefix, rest) = match doctype_end {
            Some(e) => (s[..e].to_string(), s[e..].to_string()),
            None => (String::new(), s.clone()),
        };
        let rest_trimmed = rest.trim_start_matches('\n').to_string();
        s = format!("{}<html><head></head><body>{}\n</body></html>", prefix, rest_trimmed);
    } else {
        if !lower.contains("<head") {
            // Insert empty head after <html>
            if let Some(pos) = lower.find("<html") {
                if let Some(gt) = s[pos..].find('>') {
                    let insert_at = pos + gt + 1;
                    s = format!("{}<head></head>{}", &s[..insert_at], &s[insert_at..]);
                }
            }
        }
        let lower2 = s.to_ascii_lowercase();
        if !lower2.contains("<body") {
            // Insert <body> after </head> if present, else before </html>
            if let Some(head_end) = lower2.find("</head>") {
                let insert_at = head_end + "</head>".len();
                s = format!("{}<body>{}", &s[..insert_at], &s[insert_at..]);
                // Close body before </html>
                let lower3 = s.to_ascii_lowercase();
                if let Some(html_end) = lower3.rfind("</html>") {
                    s = format!("{}</body>{}", &s[..html_end], &s[html_end..]);
                }
            }
        }
    }
    s
}

pub fn transform(input: &str, opts: &Options, doc_url: &str, _is_local: bool) -> String {
    let mut s = input.to_string();

    // Only do HTML transformations if it looks like HTML.
    if !looks_like_html(&s) {
        // Plain text passthrough.
        // Ensure trailing newline preserved as-is.
        return s;
    }

    s = ensure_html_wrapper(s);

    // Replace javascript: URLs when -j is set.
    if opts.no_js {
        s = replace_javascript_urls(&s);
        s = empty_script_tags(&s);
    }

    // Empty style tags when -c
    if opts.no_css {
        s = empty_style_tags(&s);
        s = remove_stylesheet_href(&s);
    }

    // Remove iframe src when -f
    if opts.no_frames {
        s = clear_iframe_src(&s);
    }

    // Remove audio src when -a
    if opts.no_audio {
        s = clear_attr_in_tag(&s, "audio", &["src"]);
        s = clear_source_in_parent(&s, "audio");
    }

    // Remove video src when -v
    if opts.no_video {
        s = clear_attr_in_tag(&s, "video", &["src"]);
        s = clear_source_in_parent(&s, "video");
    }

    // Images
    if opts.no_images {
        s = replace_images(&s);
    }

    // Base URL
    if let Some(base) = &opts.base_url {
        s = insert_base_tag(&s, base);
        s = rewrite_hrefs_to_absolute(&s, base);
    } else if doc_url.starts_with("http://") || doc_url.starts_with("https://") {
        s = rewrite_hrefs_to_absolute(&s, doc_url);
    }

    // Isolate
    if opts.isolate {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'unsafe-eval' 'unsafe-inline' data:;\"></meta>");
    }
    // CSP inserts based on flags
    if opts.no_css {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"style-src 'none';\"></meta>");
    }
    if opts.no_frames {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"frame-src 'none'; child-src 'none';\"></meta>");
    }
    if opts.no_images {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"img-src data:;\"></meta>");
    }
    if opts.no_js {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"script-src 'none';\"></meta>");
    }

    // Unwrap noscript
    if opts.unwrap_noscript {
        s = unwrap_noscript_tags(&s);
    }

    // Insert robots meta and normalize existing one.
    s = set_robots_meta(&s);

    s
}

fn insert_meta_head(s: &str, tag: &str) -> String {
    let lower = s.to_ascii_lowercase();
    if let Some(pos) = lower.find("<head") {
        if let Some(gt) = s[pos..].find('>') {
            let insert_at = pos + gt + 1;
            return format!("{}{}{}", &s[..insert_at], tag, &s[insert_at..]);
        }
    }
    s.to_string()
}

fn set_robots_meta(s: &str) -> String {
    // If there's an existing <meta name="robots" ...>, replace its content attribute to "none".
    // Otherwise, append a new <meta name="robots" content="none"></meta> to head.
    let lower = s.to_ascii_lowercase();
    let marker = "<meta";
    let mut pos = 0;
    while let Some(rel) = lower[pos..].find(marker) {
        let tag_start = pos + rel;
        let tag_end_rel = lower[tag_start..].find('>').unwrap_or(0);
        let tag_end = tag_start + tag_end_rel + 1;
        let tag = &s[tag_start..tag_end];
        let tag_lower = tag.to_ascii_lowercase();
        if tag_lower.contains("name=\"robots\"") || tag_lower.contains("name='robots'") {
            // Replace content attribute.
            let new_tag = replace_attr(tag, "content", "none");
            return format!("{}{}{}", &s[..tag_start], new_tag, &s[tag_end..]);
        }
        pos = tag_end;
    }
    // Append new meta to head (just before </head>).
    let new_meta = "<meta name=\"robots\" content=\"none\"></meta>";
    if let Some(head_close) = s.to_ascii_lowercase().find("</head>") {
        return format!("{}{}{}", &s[..head_close], new_meta, &s[head_close..]);
    }
    // If no </head>, insert after <head>
    if let Some(head_open) = s.to_ascii_lowercase().find("<head") {
        if let Some(gt) = s[head_open..].find('>') {
            let insert_at = head_open + gt + 1;
            return format!("{}{}</head>{}", &s[..insert_at], new_meta, &s[insert_at..]);
        }
    }
    s.to_string()
}

fn replace_attr(tag: &str, attr: &str, value: &str) -> String {
    // naive: find attr=... and replace the value
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    if let Some(p) = lower.find(&marker) {
        let after = p + marker.len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let prefix = &tag[..after];
        let suffix_start = after + val_start + end + close_extra;
        let suffix = &tag[suffix_start..];
        return format!("{}\"{}\"{}", prefix, value, suffix);
    }
    // attr not present: insert before closing '>'
    if let Some(p) = tag.rfind('>') {
        return format!("{} {}=\"{}\"{}", &tag[..p], attr, value, &tag[p..]);
    }
    tag.to_string()
}

fn replace_javascript_urls(s: &str) -> String {
    // Replace href="javascript:..." with href="javascript:;"
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < bytes.len() {
        if bytes[i] == b'"' || bytes[i] == b'\'' {
            let quote = bytes[i] as char;
            out.push(quote);
            let end = s[i+1..].find(quote).map(|e| i + 1 + e).unwrap_or(s.len());
            let inside = &s[i+1..end];
            if inside.to_ascii_lowercase().starts_with("javascript:") {
                out.push_str("javascript:;");
            } else {
                out.push_str(inside);
            }
            if end < s.len() {
                out.push(quote);
                i = end + 1;
            } else {
                i = s.len();
            }
            continue;
        }
        out.push(bytes[i] as char);
        i += 1;
    }
    out
}

fn empty_script_tags(s: &str) -> String {
    empty_tag_contents(s, "script")
}

fn empty_style_tags(s: &str) -> String {
    empty_tag_contents(s, "style")
}

fn empty_tag_contents(s: &str, tag: &str) -> String {
    let open = format!("<{}", tag);
    let close = format!("</{}>", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let tag_start = i + rel;
            out.push_str(&s[i..tag_start]);
            let after_start = tag_start;
            let gt_rel = lower[after_start..].find('>').unwrap_or(0);
            let tag_open_end = after_start + gt_rel + 1;
            out.push_str(&s[tag_start..tag_open_end]);
            // Find closing
            if let Some(close_rel) = lower[tag_open_end..].find(&close) {
                let close_start = tag_open_end + close_rel;
                let close_end = close_start + close.len();
                // Skip contents
                out.push_str(&s[close_start..close_end]);
                i = close_end;
            } else {
                i = tag_open_end;
            }
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn remove_stylesheet_href(s: &str) -> String {
