fn clear_attr_in_tag(s: &str, tag: &str, attrs: &[&str]) -> String {
    let open = format!("<{}", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            for a in attrs {
                tag_text = set_attr_empty(&tag_text, a);
            }
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn clear_source_in_parent(s: &str, parent: &str) -> String {
    // Within <parent>...</parent>, clear src on <source> tags.
    let open = format!("<{}", parent);
    let close = format!("</{}>", parent);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            out.push_str(&s[ts..te]);
            if let Some(cr) = lower[te..].find(&close) {
                let ce = te + cr;
                let inner = &s[te..ce];
                let processed = clear_attr_in_tag(inner, "source", &["src", "srcset"]);
                out.push_str(&processed);
                i = ce;
            } else {
                i = te;
            }
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn set_attr_empty(tag: &str, attr: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    // find attr= preceded by whitespace or < and followed by quote
    let mut pos = 0;
    while let Some(p) = lower[pos..].find(&marker) {
        let abs = pos + p;
        // Check boundary
        let prev = if abs == 0 { ' ' } else { tag.as_bytes()[abs-1] as char };
        if !(prev.is_whitespace() || prev == '<' || prev == '/') {
            pos = abs + marker.len();
            continue;
        }
        let after = abs + marker.len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let suffix_start = after + val_start + end + close_extra;
        let prefix = &tag[..after];
        let suffix = &tag[suffix_start..];
        return format!("{}\"\"{}", prefix, suffix);
    }
    tag.to_string()
}

fn remove_attr_in_tag_with_cond(s: &str, tag: &str, attr: &str, cond_attr: &str, cond_val: &str) -> String {
    let open = format!("<{}", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            let tl = tag_text.to_ascii_lowercase();
            let cond_marker = format!("{}=\"{}\"", cond_attr, cond_val);
            if tl.contains(&cond_marker) {
                tag_text = remove_attr(&tag_text, attr);
            }
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn remove_attr(tag: &str, attr: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    if let Some(p) = lower.find(&marker) {
        let start = p;
        // Expand start to include preceding whitespace
        let mut real_start = start;
        while real_start > 0 && (tag.as_bytes()[real_start-1] == b' ' || tag.as_bytes()[real_start-1] == b'\t') {
            real_start -= 1;
        }
        let after = start + marker.len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let suffix_start = after + val_start + end + close_extra;
        return format!("{}{}", &tag[..real_start], &tag[suffix_start..]);
    }
    tag.to_string()
}

fn replace_images(s: &str) -> String {
    let placeholder = "data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82";
    let mut out = set_attr_value_in_tag(s, "img", "src", placeholder);
    out = set_attr_value_in_tag(&out, "source", "srcset", placeholder);
    out
}

fn set_attr_value_in_tag(s: &str, tag: &str, attr: &str, value: &str) -> String {
    let open = format!("<{}", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            // Ensure next char is whitespace or > (so we don't match <source in <sourceabc)
            let after_open = ts + open.len();
            let next = s.as_bytes().get(after_open).copied().unwrap_or(b' ');
            if !(next == b' ' || next == b'\t' || next == b'>' || next == b'\n' || next == b'/') {
                out.push_str(&s[i..after_open]);
                i = after_open;
                continue;
            }
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            tag_text = set_or_add_attr(&tag_text, attr, value);
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn set_or_add_attr(tag: &str, attr: &str, value: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    if lower.contains(&marker) {
        return replace_attr(tag, attr, value);
    }
    // add it
    // remove trailing '>' and '/'
    let t = tag.trim_end_matches('>');
    let t = t.trim_end();
    let self_closing = t.ends_with('/');
    let t = t.trim_end_matches('/');
    let t = t.trim_end();
    if self_closing {
        format!("{} {}=\"{}\"/>", t, attr, value)
    } else {
        format!("{} {}=\"{}\">", t, attr, value)
    }
}

fn insert_base_tag(s: &str, base: &str) -> String {
    // Insert <base href="..."></base> right after <head>.
    let lower = s.to_ascii_lowercase();
    if lower.contains("<base") { return s.to_string(); }
    if let Some(pos) = lower.find("<head") {
        if let Some(gt) = s[pos..].find('>') {
            let insert_at = pos + gt + 1;
            let tag = format!("<base href=\"{}\"></base>", base);
            return format!("{}{}{}", &s[..insert_at], tag, &s[insert_at..]);
        }
    }
    s.to_string()
}

fn rewrite_hrefs_to_absolute(s: &str, base: &str) -> String {
    // Rewrite href values in <a> tags to be absolute URLs relative to base.
    let mut out = String::with_capacity(s.len());
    let lower = s.to_ascii_lowercase();
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find("<a") {
            let ts = i + rel;
            let after_open = ts + 2;
            let next = s.as_bytes().get(after_open).copied().unwrap_or(b' ');
            if !(next == b' ' || next == b'\t' || next == b'>' || next == b'\n') {
                out.push_str(&s[i..after_open]);
                i = after_open;
                continue;
            }
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            tag_text = rewrite_href_attr(&tag_text, base);
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn rewrite_href_attr(tag: &str, base: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    if let Some(p) = lower.find("href=") {
        let after = p + "href=".len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let val = &val_area[..end];
        let new_val = url::join(base, val);
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let suffix_start = after + val_start + end + close_extra;
        return format!("{}\"{}\"{}", &tag[..after], new_val, &tag[suffix_start..]);
    }
    tag.to_string()
}

fn unwrap_noscript_tags(s: &str) -> String {
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find("<noscript") {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            out.push_str("<!--noscript-->");
            if let Some(cr) = lower[te..].find("</noscript>") {
                let ce = te + cr;
                let end = ce + "</noscript>".len();
                out.push_str(&s[te..ce]);
                out.push_str("<!--/noscript-->");
                i = end;
            } else {
                i = te;
            }
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

pub fn wrap_mhtml(html: &str, url: &str) -> String {
    let boundary = "----=_NextPart_000_0000";
    let mut s = String::new();
    s.push_str("MIME-Version: 1.0\r\n");
    s.push_str(&format!("Content-Type: multipart/related; boundary=\"{}\"\r\n", boundary));
    s.push_str("\r\n");
    s.push_str(&format!("--{}\r\n", boundary));
    s.push_str("Content-Type: text/html; charset=\"utf-8\"\r\n");
    let loc = if url.starts_with("http://") || url.starts_with("https://") {
        url.to_string()
    } else {
        "http://example.com/".to_string()
    };
    s.push_str(&format!("Content-Location: {}\r\n", loc));
    s.push_str("\r\n");
    s.push_str(html);
    if !html.ends_with('\n') { s.push_str("\r\n"); }
    s.push_str(&format!("--{}--\r\n", boundary));
    // Normalize to \n (matches what we saw in tests).
    s.replace("\r\n", "\n")
}
