// HTML transformations.

use crate::cli::Options;
use crate::url;

/// Whether the content looks like HTML (very rough heuristic).
pub fn looks_like_html(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    lower.contains("<html") || lower.contains("<!doctype") || lower.contains("<body") || lower.contains("<head")
        || lower.contains("<div") || lower.contains("<p") || lower.contains("<span") || lower.contains("<script")
        || lower.contains("<h1") || lower.contains("<style") || lower.contains("<a ") || lower.contains("<img")
        || lower.contains("<meta") || lower.contains("<!--")
}

pub fn extract_title(s: &str) -> Option<String> {
    let lower = s.to_ascii_lowercase();
    let start = lower.find("<title")?;
    let after = &s[start..];
    let gt = after.find('>')?;
    let after_tag = &after[gt+1..];
    let end_rel = after_tag.to_ascii_lowercase().find("</title>")?;
    Some(after_tag[..end_rel].trim().to_string())
}

fn ensure_html_wrapper(mut s: String) -> String {
    let lower = s.to_ascii_lowercase();
    if !lower.contains("<html") {
        let doctype_end = if let Some(p) = lower.find("<!doctype") {
            s[p..].find('>').map(|e| p + e + 1)
        } else { None };
        let (prefix, rest) = match doctype_end {
            Some(e) => (s[..e].to_string(), s[e..].to_string()),
            None => (String::new(), s.clone()),
        };
        let rest_trimmed = rest.trim_start_matches('\n').to_string();
        s = format!("{}<html><head></head><body>{}\n</body></html>", prefix, rest_trimmed);
    } else {
        if !lower.contains("<head") {
            // Insert empty head after <html>
            if let Some(pos) = lower.find("<html") {
                if let Some(gt) = s[pos..].find('>') {
                    let insert_at = pos + gt + 1;
                    s = format!("{}<head></head>{}", &s[..insert_at], &s[insert_at..]);
                }
            }
        }
        let lower2 = s.to_ascii_lowercase();
        if !lower2.contains("<body") {
            // Insert <body> after </head> if present, else before </html>
            if let Some(head_end) = lower2.find("</head>") {
                let insert_at = head_end + "</head>".len();
                s = format!("{}<body>{}", &s[..insert_at], &s[insert_at..]);
                // Close body before </html>
                let lower3 = s.to_ascii_lowercase();
                if let Some(html_end) = lower3.rfind("</html>") {
                    s = format!("{}</body>{}", &s[..html_end], &s[html_end..]);
                }
            }
        }
    }
    s
}

pub fn transform(input: &str, opts: &Options, doc_url: &str, _is_local: bool) -> String {
    let mut s = input.to_string();

    // Only do HTML transformations if it looks like HTML.
    if !looks_like_html(&s) {
        // Plain text passthrough.
        // Ensure trailing newline preserved as-is.
        return s;
    }

    s = ensure_html_wrapper(s);

    // Replace javascript: URLs when -j is set.
    if opts.no_js {
        s = replace_javascript_urls(&s);
        s = empty_script_tags(&s);
    }

    // Empty style tags when -c
    if opts.no_css {
        s = empty_style_tags(&s);
        s = remove_stylesheet_href(&s);
    }

    // Remove iframe src when -f
    if opts.no_frames {
        s = clear_iframe_src(&s);
    }

    // Remove audio src when -a
    if opts.no_audio {
        s = clear_attr_in_tag(&s, "audio", &["src"]);
        s = clear_source_in_parent(&s, "audio");
    }

    // Remove video src when -v
    if opts.no_video {
        s = clear_attr_in_tag(&s, "video", &["src"]);
        s = clear_source_in_parent(&s, "video");
    }

    // Images
    if opts.no_images {
        s = replace_images(&s);
    }

    // Base URL
    if let Some(base) = &opts.base_url {
        s = insert_base_tag(&s, base);
        s = rewrite_hrefs_to_absolute(&s, base);
    } else if doc_url.starts_with("http://") || doc_url.starts_with("https://") {
        s = rewrite_hrefs_to_absolute(&s, doc_url);
    }

    // Isolate
    if opts.isolate {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'unsafe-eval' 'unsafe-inline' data:;\"></meta>");
    }
    // CSP inserts based on flags
    if opts.no_css {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"style-src 'none';\"></meta>");
    }
    if opts.no_frames {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"frame-src 'none'; child-src 'none';\"></meta>");
    }
    if opts.no_images {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"img-src data:;\"></meta>");
    }
    if opts.no_js {
        s = insert_meta_head(&s, "<meta http-equiv=\"Content-Security-Policy\" content=\"script-src 'none';\"></meta>");
    }

    // Unwrap noscript
    if opts.unwrap_noscript {
        s = unwrap_noscript_tags(&s);
    }

    // Insert robots meta and normalize existing one.
    s = set_robots_meta(&s);

    s
}

fn insert_meta_head(s: &str, tag: &str) -> String {
    let lower = s.to_ascii_lowercase();
    if let Some(pos) = lower.find("<head") {
        if let Some(gt) = s[pos..].find('>') {
            let insert_at = pos + gt + 1;
            return format!("{}{}{}", &s[..insert_at], tag, &s[insert_at..]);
        }
    }
    s.to_string()
}

fn set_robots_meta(s: &str) -> String {
    // If there's an existing <meta name="robots" ...>, replace its content attribute to "none".
    // Otherwise, append a new <meta name="robots" content="none"></meta> to head.
    let lower = s.to_ascii_lowercase();
    let marker = "<meta";
    let mut pos = 0;
    while let Some(rel) = lower[pos..].find(marker) {
        let tag_start = pos + rel;
        let tag_end_rel = lower[tag_start..].find('>').unwrap_or(0);
        let tag_end = tag_start + tag_end_rel + 1;
        let tag = &s[tag_start..tag_end];
        let tag_lower = tag.to_ascii_lowercase();
        if tag_lower.contains("name=\"robots\"") || tag_lower.contains("name='robots'") {
            // Replace content attribute.
            let new_tag = replace_attr(tag, "content", "none");
            return format!("{}{}{}", &s[..tag_start], new_tag, &s[tag_end..]);
        }
        pos = tag_end;
    }
    // Append new meta to head (just before </head>).
    let new_meta = "<meta name=\"robots\" content=\"none\"></meta>";
    if let Some(head_close) = s.to_ascii_lowercase().find("</head>") {
        return format!("{}{}{}", &s[..head_close], new_meta, &s[head_close..]);
    }
    // If no </head>, insert after <head>
    if let Some(head_open) = s.to_ascii_lowercase().find("<head") {
        if let Some(gt) = s[head_open..].find('>') {
            let insert_at = head_open + gt + 1;
            return format!("{}{}</head>{}", &s[..insert_at], new_meta, &s[insert_at..]);
        }
    }
    s.to_string()
}

fn replace_attr(tag: &str, attr: &str, value: &str) -> String {
    // naive: find attr=... and replace the value
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    if let Some(p) = lower.find(&marker) {
        let after = p + marker.len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let prefix = &tag[..after];
        let suffix_start = after + val_start + end + close_extra;
        let suffix = &tag[suffix_start..];
        return format!("{}\"{}\"{}", prefix, value, suffix);
    }
    // attr not present: insert before closing '>'
    if let Some(p) = tag.rfind('>') {
        return format!("{} {}=\"{}\"{}", &tag[..p], attr, value, &tag[p..]);
    }
    tag.to_string()
}

fn replace_javascript_urls(s: &str) -> String {
    // Replace href="javascript:..." with href="javascript:;"
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < bytes.len() {
        if bytes[i] == b'"' || bytes[i] == b'\'' {
            let quote = bytes[i] as char;
            out.push(quote);
            let end = s[i+1..].find(quote).map(|e| i + 1 + e).unwrap_or(s.len());
            let inside = &s[i+1..end];
            if inside.to_ascii_lowercase().starts_with("javascript:") {
                out.push_str("javascript:;");
            } else {
                out.push_str(inside);
            }
            if end < s.len() {
                out.push(quote);
                i = end + 1;
            } else {
                i = s.len();
            }
            continue;
        }
        out.push(bytes[i] as char);
        i += 1;
    }
    out
}

fn empty_script_tags(s: &str) -> String {
    empty_tag_contents(s, "script")
}

fn empty_style_tags(s: &str) -> String {
    empty_tag_contents(s, "style")
}

fn empty_tag_contents(s: &str, tag: &str) -> String {
    let open = format!("<{}", tag);
    let close = format!("</{}>", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let tag_start = i + rel;
            out.push_str(&s[i..tag_start]);
            let after_start = tag_start;
            let gt_rel = lower[after_start..].find('>').unwrap_or(0);
            let tag_open_end = after_start + gt_rel + 1;
            out.push_str(&s[tag_start..tag_open_end]);
            // Find closing
            if let Some(close_rel) = lower[tag_open_end..].find(&close) {
                let close_start = tag_open_end + close_rel;
                let close_end = close_start + close.len();
                // Skip contents
                out.push_str(&s[close_start..close_end]);
                i = close_end;
            } else {
                i = tag_open_end;
            }
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn remove_stylesheet_href(s: &str) -> String {
    // For <link ... rel="stylesheet" ...>, remove href attribute.
    remove_attr_in_tag_with_cond(s, "link", "href", "rel", "stylesheet")
}

fn clear_iframe_src(s: &str) -> String {
    clear_attr_in_tag(s, "iframe", &["src"])
}

fn clear_attr_in_tag(s: &str, tag: &str, attrs: &[&str]) -> String {
    let open = format!("<{}", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            for a in attrs {
                tag_text = set_attr_empty(&tag_text, a);
            }
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn clear_source_in_parent(s: &str, parent: &str) -> String {
    // Within <parent>...</parent>, clear src on <source> tags.
    let open = format!("<{}", parent);
    let close = format!("</{}>", parent);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            out.push_str(&s[ts..te]);
            if let Some(cr) = lower[te..].find(&close) {
                let ce = te + cr;
                let inner = &s[te..ce];
                let processed = clear_attr_in_tag(inner, "source", &["src", "srcset"]);
                out.push_str(&processed);
                i = ce;
            } else {
                i = te;
            }
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn set_attr_empty(tag: &str, attr: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    // find attr= preceded by whitespace or < and followed by quote
    let mut pos = 0;
    while let Some(p) = lower[pos..].find(&marker) {
        let abs = pos + p;
        // Check boundary
        let prev = if abs == 0 { ' ' } else { tag.as_bytes()[abs-1] as char };
        if !(prev.is_whitespace() || prev == '<' || prev == '/') {
            pos = abs + marker.len();
            continue;
        }
        let after = abs + marker.len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let suffix_start = after + val_start + end + close_extra;
        let prefix = &tag[..after];
        let suffix = &tag[suffix_start..];
        return format!("{}\"\"{}", prefix, suffix);
    }
    tag.to_string()
}

fn remove_attr_in_tag_with_cond(s: &str, tag: &str, attr: &str, cond_attr: &str, cond_val: &str) -> String {
    let open = format!("<{}", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            let tl = tag_text.to_ascii_lowercase();
            let cond_marker = format!("{}=\"{}\"", cond_attr, cond_val);
            if tl.contains(&cond_marker) {
                tag_text = remove_attr(&tag_text, attr);
            }
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn remove_attr(tag: &str, attr: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    if let Some(p) = lower.find(&marker) {
        let start = p;
        // Expand start to include preceding whitespace
        let mut real_start = start;
        while real_start > 0 && (tag.as_bytes()[real_start-1] == b' ' || tag.as_bytes()[real_start-1] == b'\t') {
            real_start -= 1;
        }
        let after = start + marker.len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let suffix_start = after + val_start + end + close_extra;
        return format!("{}{}", &tag[..real_start], &tag[suffix_start..]);
    }
    tag.to_string()
}

fn replace_images(s: &str) -> String {
    let placeholder = "data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82";
    let mut out = set_attr_value_in_tag(s, "img", "src", placeholder);
    out = set_attr_value_in_tag(&out, "source", "srcset", placeholder);
    out
}

fn set_attr_value_in_tag(s: &str, tag: &str, attr: &str, value: &str) -> String {
    let open = format!("<{}", tag);
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find(&open) {
            let ts = i + rel;
            // Ensure next char is whitespace or > (so we don't match <source in <sourceabc)
            let after_open = ts + open.len();
            let next = s.as_bytes().get(after_open).copied().unwrap_or(b' ');
            if !(next == b' ' || next == b'\t' || next == b'>' || next == b'\n' || next == b'/') {
                out.push_str(&s[i..after_open]);
                i = after_open;
                continue;
            }
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            tag_text = set_or_add_attr(&tag_text, attr, value);
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn set_or_add_attr(tag: &str, attr: &str, value: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    let marker = format!("{}=", attr.to_ascii_lowercase());
    if lower.contains(&marker) {
        return replace_attr(tag, attr, value);
    }
    // add it
    // remove trailing '>' and '/'
    let t = tag.trim_end_matches('>');
    let t = t.trim_end();
    let self_closing = t.ends_with('/');
    let t = t.trim_end_matches('/');
    let t = t.trim_end();
    if self_closing {
        format!("{} {}=\"{}\"/>", t, attr, value)
    } else {
        format!("{} {}=\"{}\">", t, attr, value)
    }
}

fn insert_base_tag(s: &str, base: &str) -> String {
    // Insert <base href="..."></base> right after <head>.
    let lower = s.to_ascii_lowercase();
    if lower.contains("<base") { return s.to_string(); }
    if let Some(pos) = lower.find("<head") {
        if let Some(gt) = s[pos..].find('>') {
            let insert_at = pos + gt + 1;
            let tag = format!("<base href=\"{}\"></base>", base);
            return format!("{}{}{}", &s[..insert_at], tag, &s[insert_at..]);
        }
    }
    s.to_string()
}

fn rewrite_hrefs_to_absolute(s: &str, base: &str) -> String {
    // Rewrite href values in <a> tags to be absolute URLs relative to base.
    let mut out = String::with_capacity(s.len());
    let lower = s.to_ascii_lowercase();
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find("<a") {
            let ts = i + rel;
            let after_open = ts + 2;
            let next = s.as_bytes().get(after_open).copied().unwrap_or(b' ');
            if !(next == b' ' || next == b'\t' || next == b'>' || next == b'\n') {
                out.push_str(&s[i..after_open]);
                i = after_open;
                continue;
            }
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            let mut tag_text = s[ts..te].to_string();
            tag_text = rewrite_href_attr(&tag_text, base);
            out.push_str(&tag_text);
            i = te;
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

fn rewrite_href_attr(tag: &str, base: &str) -> String {
    let lower = tag.to_ascii_lowercase();
    if let Some(p) = lower.find("href=") {
        let after = p + "href=".len();
        let rest = &tag[after..];
        let (quote, val_start) = match rest.chars().next() {
            Some('"') => ('"', 1),
            Some('\'') => ('\'', 1),
            _ => (' ', 0),
        };
        let val_area = &rest[val_start..];
        let end = if quote == ' ' {
            val_area.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(val_area.len())
        } else {
            val_area.find(quote).unwrap_or(val_area.len())
        };
        let val = &val_area[..end];
        let new_val = url::join(base, val);
        let close_extra = if quote == ' ' { 0 } else { 1 };
        let suffix_start = after + val_start + end + close_extra;
        return format!("{}\"{}\"{}", &tag[..after], new_val, &tag[suffix_start..]);
    }
    tag.to_string()
}

fn unwrap_noscript_tags(s: &str) -> String {
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if let Some(rel) = lower[i..].find("<noscript") {
            let ts = i + rel;
            out.push_str(&s[i..ts]);
            let gt_rel = lower[ts..].find('>').unwrap_or(0);
            let te = ts + gt_rel + 1;
            out.push_str("<!--noscript-->");
            if let Some(cr) = lower[te..].find("</noscript>") {
                let ce = te + cr;
                let end = ce + "</noscript>".len();
                out.push_str(&s[te..ce]);
                out.push_str("<!--/noscript-->");
                i = end;
            } else {
                i = te;
            }
        } else {
            out.push_str(&s[i..]);
            break;
        }
    }
    out
}

pub fn wrap_mhtml(html: &str, url: &str) -> String {
    let boundary = "----=_NextPart_000_0000";
    let mut s = String::new();
    s.push_str("MIME-Version: 1.0\r\n");
    s.push_str(&format!("Content-Type: multipart/related; boundary=\"{}\"\r\n", boundary));
    s.push_str("\r\n");
    s.push_str(&format!("--{}\r\n", boundary));
    s.push_str("Content-Type: text/html; charset=\"utf-8\"\r\n");
    let loc = if url.starts_with("http://") || url.starts_with("https://") {
        url.to_string()
    } else {
        "http://example.com/".to_string()
    };
    s.push_str(&format!("Content-Location: {}\r\n", loc));
    s.push_str("\r\n");
    s.push_str(html);
    if !html.ends_with('\n') { s.push_str("\r\n"); }
    s.push_str(&format!("--{}--\r\n", boundary));
    // Normalize to \n (matches what we saw in tests).
    s.replace("\r\n", "\n")
}
